CREATE OR REPLACE FUNCTION public.protect_access_state() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF current_user NOT IN ('postgres','supabase_admin') AND auth.role() IS DISTINCT FROM 'service_role' AND (NEW.suspended_at IS DISTINCT FROM OLD.suspended_at OR (TG_TABLE_NAME='shops' AND to_jsonb(NEW)->'archived_at' IS DISTINCT FROM to_jsonb(OLD)->'archived_at')) THEN RAISE EXCEPTION 'Access state is server managed' USING ERRCODE='42501'; END IF; RETURN NEW; END; $$;